class Solution {
    public String removeKdigits(String num, int k) {
        char[] st = new char[num.length()];
        int top = 0;
        for (int i = 0; i < num.length(); i++) {
            char d = num.charAt(i);
            while (k > 0 && top > 0 && st[top - 1] > d) {
                top--;
                k--;
            }
            st[top++] = d;
        }
        top -= k;
        int start = 0;
        while (start < top && st[start] == '0') start++;
        if (start >= top) return "0";
        return new String(st, start, top - start);
    }
}

var removeKdigits = function(num, k) {
    const st = [];
    for (let i = 0; i < num.length; i++) {
        const d = num[i];
        while (k > 0 && st.length > 0 && st[st.length - 1] > d) {
            st.pop();
            k--;
        }
        st.push(d);
    }
    while (k > 0) {
        st.pop();
        k--;
    }
    let res = st.join('').replace(/^0+/, '');
    return res === '' ? '0' : res;
};
